<?php $formItems = old('items', $items); $errors = session('errors') ?? []; ?>
<?= view('admin/partials/shell_start', ['pageTitle' => 'Edit quote', 'activeSection' => 'quotes', 'businessName' => $businessName]) ?>
<main class="admin-main admin-main-wide">
    <a class="admin-back-link" href="/admin/quotes">&larr; Quotes</a>
    <div class="admin-page-heading admin-quote-heading"><div><p class="admin-kicker"><?= esc($quote['quote_number']) ?> &middot; VERSION <?= (int) $quote['version'] ?></p><h1><?= esc($quote['customer_business_name'] ?: $quote['customer_name']) ?></h1><p><?= esc($quote['customer_name']) ?> &middot; <?= esc($quote['customer_email']) ?><?php if ($request): ?> &middot; <a href="/admin/quote-requests/<?= (int) $request['id'] ?>"><?= esc($request['reference_number']) ?></a><?php endif ?></p></div><span class="admin-status admin-status-<?= esc($quote['status'], 'attr') ?>"><?= esc($statuses[$quote['status']] ?? ucfirst($quote['status'])) ?></span></div>
    <?php if (session('message')): ?><div class="notice" role="status"><?= esc(session('message')) ?></div><?php endif ?>
    <?php if ($errors !== []): ?><div class="notice notice-error" role="alert">Please review the quote fields and line items.</div><?php endif ?>
    <form class="admin-quote-editor" action="/admin/quotes/<?= (int) $quote['id'] ?>" method="post" data-quote-editor>
        <?= csrf_field() ?>
        <div class="admin-quote-editor-main">
            <section class="admin-quote-panel"><div class="admin-panel-heading"><h2>Quote details</h2><p>Dates, currency, and current workflow state.</p></div><div class="form-grid admin-quote-metadata"><div class="form-row"><label for="quote-date">Quote date</label><input id="quote-date" type="date" name="quote_date" value="<?= esc(old('quote_date', $quote['quote_date']), 'attr') ?>"></div><div class="form-row"><label for="expires-on">Expires on</label><input id="expires-on" type="date" name="expires_on" value="<?= esc(old('expires_on', $quote['expires_on']), 'attr') ?>"><?php if (isset($errors['expires_on'])): ?><p class="field-error"><?= esc($errors['expires_on']) ?></p><?php endif ?></div><div class="form-row"><label for="currency-code">Currency</label><input id="currency-code" name="currency_code" maxlength="3" value="<?= esc(old('currency_code', $quote['currency_code']), 'attr') ?>"></div><div class="form-row"><label for="quote-status">Status</label><select id="quote-status" name="status"><?php foreach ($statuses as $value => $label): ?><option value="<?= esc($value, 'attr') ?>" <?= old('status', $quote['status']) === $value ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach ?></select></div></div></section>
            <section class="admin-quote-panel"><div class="admin-panel-heading admin-panel-heading-action"><div><h2>Line items</h2><p>Use deliverables and prices that reflect the actual scope.</p></div><button class="admin-secondary-action" type="button" data-add-line>+ Add line</button></div><?php if (isset($errors['items'])): ?><p class="field-error"><?= esc($errors['items']) ?></p><?php endif ?><div class="admin-line-items" data-line-items><?php foreach (array_values($formItems) as $index => $item): ?><?= view('admin/quotes/_line_item', ['index' => $index, 'item' => $item, 'errors' => $errors]) ?><?php endforeach ?></div><template data-line-template><?= view('admin/quotes/_line_item', ['index' => '__INDEX__', 'item' => ['description' => '', 'details' => '', 'quantity' => '1.00', 'unit_price' => '0.00'], 'errors' => []]) ?></template></section>
            <section class="admin-quote-panel"><div class="admin-panel-heading"><h2>Terms and notes</h2><p>Customer-facing conditions and additional context.</p></div><div class="form-row"><label for="quote-terms">Terms</label><textarea id="quote-terms" name="terms" rows="9" maxlength="10000"><?= esc(old('terms', $quote['terms'] ?? '')) ?></textarea></div><div class="form-row"><label for="quote-notes">Notes shown to customer</label><textarea id="quote-notes" name="notes" rows="5" maxlength="5000"><?= esc(old('notes', $quote['notes'] ?? '')) ?></textarea></div></section>
        </div>
