    </form>
    <div class="admin-quote-lower"><section><h2>Status history</h2><?php foreach ($history as $entry): ?><article><span><?= esc($entry['created_at']) ?></span><strong><?= esc($entry['from_status'] ? ($statuses[$entry['from_status']] ?? $entry['from_status']) . ' to ' : '') ?><?= esc($statuses[$entry['to_status']] ?? $entry['to_status']) ?></strong><?php if ($entry['note']): ?><p><?= esc($entry['note']) ?></p><?php endif ?></article><?php endforeach ?></section><section><h2>Revisions</h2><p><?= count($versions) ?> immutable <?= count($versions) === 1 ? 'snapshot' : 'snapshots' ?> stored.</p></section><section class="admin-send-panel"><h2>Delivery</h2><p>Mark the quote ready, save it, then send the secure link by email.</p><form action="/admin/quotes/<?= (int) $quote['id'] ?>/send" method="post"><?= csrf_field() ?><button class="admin-primary-action" type="submit" <?= $quote['status'] !== 'ready' ? 'disabled' : '' ?>>Send quote</button></form></section></div>
</main>
